    CONSTRAINT wallet_transactions_direction_check CHECK (((direction)::text = ANY ((ARRAY['CREDIT'::character varying, 'DEBIT'::character varying])::text[]))),
    CONSTRAINT wallet_transactions_transaction_type_check CHECK (((transaction_type)::text = ANY ((ARRAY['DEPOSIT'::character varying, 'PURCHASE'::character varying, 'REFUND'::character varying, 'ADJUSTMENT'::character varying, 'REVERSAL'::character varying])::text[])))
);


